 * The 1-based column, in `raw`, of the value that follows the separator at index `split` of
 * `raw.trim()`: the value's first character, or, when the value is empty, one past the line's
 * last non-space character.
 */
export function valuePosition(raw, split) {
  const trimmed = raw.trim()
  const after = trimmed.slice(split + 1)
  const lead = after.length - after.trimStart().length
  if (after.trim() === '') return raw.trimEnd().length + 1
  return indent(raw) + split + 1 + lead
