/** The command: `dump <file>`, `get <file> <key>`, `load <base> <site>` and `origin <base> <site>`. */

import { existsSync, readFileSync } from 'node:fs'
import { parse as parseEnv } from './env.js'
import { IniError, parse as parseIni } from './ini.js'
import { merge } from './layer.js'
import { coerce, SETTINGS, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** One INI layer, refused at its own position when the grammar rejects it. */
function iniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    return { name, file: path, values: parseIni(readFileSync(path, 'utf8')) }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/**
 * One INI layer for `load`/`origin`: refused like `iniLayer`, and also refused, once it parses,
 * at the first key in file order the schema does not know.
 */
function strictIniLayer(name, path) {
  const layer = iniLayer(name, path)
  for (const [key, info] of layer.values) {
    if (setting(key) === undefined) fail(`${path}:${info.line}:${info.column}: unknown setting ${key}`)
  }
  return layer
}

/** The environment layer, read from standard input and refused at its own position. */
function envLayer(text) {
  try {
    return { name: 'env', file: '<stdin>', values: parseEnv(text) }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (arity[mode] === undefined || argv.length !== arity[mode]) fail(USAGE)

const out = []

if (mode === 'dump' || mode === 'get') {
  const values = merge([iniLayer('file', argv[1])])
  const raw = key => (values.has(key) ? values.get(key).text : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else {
  const base = strictIniLayer('base', argv[1])
  const site = strictIniLayer('site', argv[2])
  const env = envLayer(readFileSync(0, 'utf8'))
  const merged = merge([base, site, env])

  if (mode === 'origin') {
    for (const declared of SETTINGS) {
      const info = merged.get(declared.key)
      out.push(`${declared.key} ${info ? info.layer : 'default'}`)
    }
  } else {
    for (const declared of SETTINGS) {
      const info = merged.get(declared.key)
      const text = info ? info.text : declared.default
      const result = coerce(declared, text)
      if (!result.ok) fail(`${info.file}:${info.line}:${info.column}: ${result.message}`)
      out.push(`${declared.key}=${result.out}`)
    }
  }
}

